WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY location ORDER BY budget DESC, id) AS rank_in_group FROM departments QUALIFY rank_in_group = 1) SELECT id, dept_name, budget, rank_in_group, CASE WHEN dept_name RLIKE '^(Engineering|Legal)$' THEN 'CORE' WHEN dept_name RLIKE '^(Sales|Marketing)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS dept_name_zone FROM latest ORDER BY id NULLS FIRST;
